#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* ------------------------------------------------------------------ */
/*  Helper: check that a string consists only of the seven Roman letters */
static int only_roman_letters(const char *s)
{
    for ( ; *s; ++s )
    {
        char c = *s;
        if (c!='I' && c!='V' && c!='X' && c!='L' && c!='C' && c!='D' && c!='M')
            return 0;
    }
    return 1;
}

/* ------------------------------------------------------------------ */
/*  Helper: verify that the (already upper‑case) string follows the
 *  canonical Roman‑numeral pattern for numbers 1 … 3999.
 *
 *  Pattern (regular expression):
 *      ^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$
 *
 *  The function walks the string segment by segment; if any part does
 *  not match the pattern it returns 0, otherwise 1.
 */
static int canonical_roman(const char *s)
{
    const char *p = s;

    /* thousands: 0–3 'M' */
    int cnt = 0;
    while (*p == 'M' && cnt < 3) { ++cnt; ++p; }
    if (cnt > 3) return 0;

    /* hundreds */
    if (strncmp(p, "CM", 2) == 0) { p += 2; }
    else if (strncmp(p, "CD", 2) == 0) { p += 2; }
    else {
        if (*p == 'D') { ++p; }
        cnt = 0;
        while (*p == 'C' && cnt < 3) { ++cnt; ++p; }
        if (cnt > 3) return 0;
    }

    /* tens */
    if (strncmp(p, "XC", 2) == 0) { p += 2; }
    else if (strncmp(p, "XL", 2) == 0) { p += 2; }
    else {
        if (*p == 'L') { ++p; }
        cnt = 0;
        while (*p == 'X' && cnt < 3) { ++cnt; ++p; }
        if (cnt > 3) return 0;
    }

    /* units */
    if (strncmp(p, "IX", 2) == 0) { p += 2; }
    else if (strncmp(p, "IV", 2) == 0) { p += 2; }
    else {
        if (*p == 'V') { ++p; }
        cnt = 0;
        while (*p == 'I' && cnt < 3) { ++cnt; ++p; }
        if (cnt > 3) return 0;
    }

    /* must have consumed the whole string */
    return *p == '\0';
}

/* ------------------------------------------------------------------ */
/*  Convert a *canonical* Roman numeral (upper‑case) to its integer value.
 *  The function assumes the input is valid; it simply walks the string
 *  from left to right, adding the value of the longest matching symbol.
 */
static int roman_to_int(const char *s)
{
    static const struct { const char *sym; int val; } table[] = {
        {"M",  1000},
        {"CM",  900},
        {"D",   500},
        {"CD",  400},
        {"C",   100},
        {"XC",   90},
        {"L",    50},
        {"XL",   40},
        {"X",    10},
        {"IX",    9},
        {"V",     5},
        {"IV",    4},
        {"I",     1},
        {NULL,    0}
    };

    int total = 0;
    const char *p = s;

    for (int i = 0; table[i].sym != NULL; ++i) {
        size_t sl = strlen(table[i].sym);
        while (strncmp(p, table[i].sym, sl) == 0) {
            total += table[i].val;
            p += sl;
        }
    }
    return total;
}

/* ------------------------------------------------------------------ */
int main(int argc, char **argv)
{
    /* The original program required exactly one argument */
    if (argc != 2) {
        puts("INVALID");
        return 0;
    }

    const char *orig = argv[1];
    size_t len = strlen(orig);

    /* Empty string or overly long input is rejected */
    if (len == 0 || len > 63) {
        puts("INVALID");
        return 0;
    }

    /* Build an upper‑case copy */
    char upper[64];
    for (size_t i = 0; i < len; ++i)
        upper[i] = (char) toupper((unsigned char)orig[i]);
    upper[len] = '\0';

    /* Characters must be among the seven Roman letters */
    if (!only_roman_letters(upper)) {
        puts("INVALID");
        return 0;
    }

    /* Must follow the canonical pattern */
    if (!canonical_roman(upper)) {
        puts("INVALID");
        return 0;
    }

    /* Convert to integer (the value is guaranteed ≤ 3999 by the pattern) */
    int value = roman_to_int(upper);
    if (value < 1 || value > 3999) {          /* safety check */
        puts("INVALID");
        return 0;
    }

    printf("%d\n", value);
    return 0;
}
